const index=m=>Number(m.slice(0,4))*12+Number(m.slice(5))-1;
export function policyFor(month){const event=POLICY_EVENTS.findLast(e=>e.month<=month);if(!event||index(month)-index(event.month)>=60)return null;return {eventId:event.id,month:event.month,...event.policy};}
export function policyWeight(policy,month){if(!policy)return 0;const elapsed=index(month)-index(policy.month);return elapsed>=0&&elapsed<60?Math.max(.25,1-elapsed/80):0;}
export function policyEffects(raw,policy,month){const w=policyWeight(policy,month);if(!w)return;for(const [id,tilt] of Object.entries(policy.tilt))raw[id]*=1+tilt*w;}
export function policyTargets(policy,month){const w=policyWeight(policy,month);return {deposit:.025+(policy?.depositBias||0)*w,inflation:.025+(policy?.inflationBias||0)*w};}
